package apidserver

import (
	"net/http"

	"github.com/onebox-faas/faas/pkg/api"
	"github.com/onebox-faas/faas/pkg/apid/managedpg"
)

func (s *server) registerOrgPostgresRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.listManagedPostgresDatabases))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/capabilities", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresCapabilities))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.createManagedPostgresDatabase))))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/compute-policy", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.changeManagedPostgresComputePolicy)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/compute-policy-changes/{change_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresComputePolicyChange))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/suspend-timeout", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.setManagedPostgresSuspendTimeout)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/resize", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.managedPostgresResize(managedpg.Resizes.Post))))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/resizes/{resize_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.managedPostgresResize(managedpg.Resizes.Get)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresDatabase))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/postgres/databases/{id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.idempotent(s.deleteManagedPostgresDatabase)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/undelete", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.undeleteManagedPostgresDatabase))))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/migration-check", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.checkManagedPostgresMigration)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/migration", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.startManagedPostgresMigration)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/migration/stop", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.stopManagedPostgresMigration)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/migration/prepare", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.prepareManagedPostgresMigration)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/migration/verify", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.verifyManagedPostgresMigration)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/migration", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresMigration))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/imports/check", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.checkManagedPostgresImport)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/backup-schedule", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.getManagedPostgresBackupSchedule))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/backup-schedule", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireScope(api.ScopesStorageWriteSurface...)(s.requireVerifiedEmail(s.setManagedPostgresBackupSchedule))))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/postgres/databases/{id}/backup-schedule", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.deleteManagedPostgresBackupSchedule)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/exports", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.startManagedPostgresExport)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/exports/{export_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.getManagedPostgresExport)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/exports/{export_id}/download", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.downloadManagedPostgresExport)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/imports", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.startManagedPostgresImport)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/imports/{operation_id}/archive", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.uploadManagedPostgresArchive)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/imports/{operation_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresImport))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/restore-check", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.checkManagedPostgresRestore))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/restore-drills/{drill_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.managedPostgresRestoreDrill))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/upgrade-rehearsals/{rehearsal_id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.managedPostgresUpgradeRehearsal))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/restore-drills", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.managedPostgresRestoreDrill)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/upgrade-rehearsals", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.managedPostgresUpgradeRehearsal)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/diagnostics", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresDiagnostics))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/tables", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresTableHealth))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/extensions", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.managedPostgresExtensions))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/extensions/{extension}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.managedPostgresExtensions)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/errors", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresErrorHistory))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/errors", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.setManagedPostgresErrorHistory)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/query-insights", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresQueryInsights))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/query-insights", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.setManagedPostgresQueryInsights)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/autovacuum", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.managedPostgresAutovacuum))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/autovacuum", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.managedPostgresAutovacuum)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/sessions", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.listManagedPostgresSessions))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/cancel-query", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.cancelManagedPostgresQuery)))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/databases/{id}/recovery-region", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.setManagedPostgresRecoveryRegion)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/restore", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.restoreManagedPostgresDatabase))))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/masked-branches", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.createManagedPostgresMaskedBranch))))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/databases/{id}/bindings", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.listManagedPostgresBindings))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/databases/{id}/bindings", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.createManagedPostgresBinding))))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/bindings/{id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresBinding))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/postgres/bindings/{id}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.idempotent(s.deleteManagedPostgresBinding)))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/bindings/{id}/timeouts", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresReadSurface...)(s.getManagedPostgresBindingTimeouts))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/postgres/bindings/{id}/timeouts", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.setManagedPostgresBindingTimeouts)))))
	mux.HandleFunc("POST /v1/orgs/{organization}/postgres/bindings/{id}/rotate", s.authLimited(s.requireMFA(s.requireScope(api.ScopesManagedPostgresManageSurface...)(s.requireVerifiedEmail(s.idempotent(s.rotateManagedPostgresBinding))))))
	mux.HandleFunc("GET /v1/orgs/{organization}/postgres/usage", s.authLimited(s.requireMFA(s.requireScope(api.ScopesUsageReadSurface...)(s.getManagedPostgresUsage))))
}
